const nonCollapsedSnippets = document.querySelectorAll(
	".frame:not(.collapsed) .code-snippet-wrapper",
);

for (const snippet of nonCollapsedSnippets) {
	snippet.style.height = `${snippet.scrollHeight}px`;
}

function toggleTracebackView() {
	const browserTraceback = document.getElementById("browserTraceback");
	const pastebinTraceback = document.getElementById("pastebinTraceback");
	const toggleBtn = document.getElementById("toggleView");

	if (browserTraceback.style.display === "none") {
		browserTraceback.style.display = "block";
		pastebinTraceback.style.display = "none";
		toggleBtn.textContent = "Plaintext view";
	} else {
		browserTraceback.style.display = "none";
		pastebinTraceback.style.display = "block";
		toggleBtn.textContent = "Interactive view";
	}
}

function copyTraceback() {
	const tracebackText = document.getElementById("traceback_area").value;
	navigator.clipboard.writeText(tracebackText).then(
		() => {
			alert("Traceback copied to clipboard!");
		},
		(err) => {
			console.error("Failed to copy traceback: ", err);
		}
	);
}

